(function(){
const DEFAULT_BO={
  name:'Alex',
  role:'Business Owner',
  responsibilities:[
    'Own the business outcomes, transformation vision and enterprise process model.',
    'Approve scope, prioritization, design principles and stage-gate exit criteria.',
    'Hold BPOs accountable for end-to-end process ownership, SME coverage and readiness.',
    'Resolve cross-value-stream conflicts and decisions that cannot be closed within a workstream.',
    'Challenge extensions and customizations and approve material business exceptions.',
    'Ensure master data, integrations, reporting, controls and organizational change are treated as business responsibilities.',
    'Review RAID, schedule exceptions and readiness indicators and escalate material items to the Steering Committee.',
    'Approve business UAT readiness and confirm business sign-off before cutover.',
    'Prepare the business go / no-go recommendation and own benefits realization after go-live.'
  ]
};
function boProfile(){return state.framework?.businessOwner||DEFAULT_BO}
function allMilestones(){return (data().milestones||[]).slice().sort((a,b)=>String(a.start||'').localeCompare(String(b.start||'')))}
function milestoneById(id){return (data().milestones||[]).find(m=>m.id===id)}
function inferTaskMilestone(t){if(t.milestoneId)return t.milestoneId;const due=t.forecastDue||t.due||'';const m=allMilestones().find(x=>due&&x.start&&x.end&&due>=x.start&&due<=x.end);return m?.id||''}
function roleForTask(t){if(t.ownerRole)return t.ownerRole;const bo=boProfile();if(t.owner===bo.name||t.owner==='Business Owner')return 'Business Owner';const p=(data().people||[]).find(x=>x.name===t.owner);return p?.role||'SME / Other'}
function milestoneName(id){const m=milestoneById(id);return m?`${m.id} · ${m.name}`:(id||'Unassigned')}
function nextTaskOrder(mid){const xs=(data().tasks||[]).filter(t=>inferTaskMilestone(t)===mid);return (Math.max(0,...xs.map(t=>Number(t.ganttOrder)||0))+10)}
function orderedTasks(items){return items.slice().sort((a,b)=>(Number(a.ganttOrder)||999999)-(Number(b.ganttOrder)||999999)||String(a.start||'').localeCompare(String(b.start||''))||String(a.title||'').localeCompare(String(b.title||'')))}
function milestoneProgress(mid){const ts=(data().tasks||[]).filter(t=>inferTaskMilestone(t)===mid);return ts.length?clampPct(avg(ts.map(taskProgress))):0}
function moveTaskInGantt(id,dir){const arr=state.tasks.tasks||[],t=arr.find(x=>x.id===id);if(!t)return;const mid=inferTaskMilestone(t),siblings=orderedTasks(arr.filter(x=>inferTaskMilestone(x)===mid)),idx=siblings.findIndex(x=>x.id===id),j=idx+dir;if(idx<0||j<0||j>=siblings.length)return;const other=siblings[j],a=Number(t.ganttOrder)||((idx+1)*10),b=Number(other.ganttOrder)||((j+1)*10);t.ganttOrder=b;other.ganttOrder=a;mark('tasks');render()}
function taskDates(t){return {start:t.start||'',end:t.forecastDue||t.due||t.baselineDue||''}}
function dateRange(ms,ts){const ds=[];ms.forEach(m=>{if(m.start)ds.push(dateAt(m.start));if(m.end)ds.push(dateAt(m.end))});ts.forEach(t=>{const d=taskDates(t);if(d.start)ds.push(dateAt(d.start));if(d.end)ds.push(dateAt(d.end))});const good=ds.filter(Boolean);if(!good.length)return null;return {min:new Date(Math.min(...good)),max:new Date(Math.max(...good))}}
function barPos(start,end,range){if(!start||!end||!range)return null;const a=dateAt(start),b=dateAt(end),span=Math.max(1,range.max-range.min);return {left:100*(a-range.min)/span,width:Math.max(1,100*(b-a)/span)} }
function workplanGantt(ms,ts){
  const range=dateRange(ms,ts);if(!range)return '<div class="card empty">No dated milestones or tasks.</div>';
  const rows=ms.map(m=>{
    const mt=orderedTasks(ts.filter(t=>inferTaskMilestone(t)===m.id)),mp=barPos(m.start,m.end,range);
    const milestoneRow=`<div class="gantt-row milestone-row"><div class="gantt-label"><b>${esc(m.id)} · ${esc(m.name)}</b><small>${mt.length} linked tasks · ${milestoneProgress(m.id)}% complete</small></div><div class="gantt-track">${mp?`<div class="gantt-bar milestone-bar" style="left:${mp.left}%;width:${mp.width}%"></div>`:''}</div></div>`;
    const taskRows=mt.map((t,i)=>{
      const d=taskDates(t),bp=barPos(d.start,d.end,range);
      return `<div class="gantt-row task-row" data-edit-task="${t.id}"><div class="gantt-label gantt-task-label"><div class="reorder-controls"><button class="mini-btn" data-move-task="${t.id}" data-dir="-1" ${i===0?'disabled':''} title="Move task up">↑</button><button class="mini-btn" data-move-task="${t.id}" data-dir="1" ${i===mt.length-1?'disabled':''} title="Move task down">↓</button></div><div><b>${esc(t.title)}</b><small>${esc(t.stream)} · ${esc(roleForTask(t))} · ${esc(t.owner||'Unassigned')} · ${esc(t.status||'')}</small></div></div><div class="gantt-track">${bp?`<div class="gantt-bar task-bar" style="left:${bp.left}%;width:${bp.width}%"></div>`:''}</div></div>`;
    }).join('');
    return milestoneRow+taskRows;
  }).join('');
  return `<div class="card gantt workplan-gantt"><div class="gantt-head"><span>${range.min.toLocaleDateString()}</span><span>${range.max.toLocaleDateString()}</span></div>${rows}</div>`;
}
function milestoneDrilldown(ms,ts){return `<div class="milestone-drilldown">${ms.map((m,idx)=>{const mt=orderedTasks(ts.filter(t=>inferTaskMilestone(t)===m.id)),streams=[...new Set(mt.map(t=>t.stream||'Program'))];return `<details class="card milestone-detail" ${idx===0?'open':''}><summary><div><span>${esc(m.id)}</span><b>${esc(m.name)}</b><small>${esc(m.start)} → ${esc(m.end)} · ${mt.length} tasks</small></div><div class="milestone-summary-progress"><strong>${milestoneProgress(m.id)}%</strong><div class="maturity-bar"><i style="width:${milestoneProgress(m.id)}%"></i></div></div></summary><div class="milestone-body">${streams.map(stream=>{const st=mt.filter(t=>(t.stream||'Program')===stream),owners=[...new Set(st.map(t=>`${roleForTask(t)}|||${t.owner||'Unassigned'}`))];return `<div class="milestone-stream"><h4>${esc(stream)} · ${esc(allStreams().find(s=>s.id===stream)?.name|| (stream==='Program'?'Program governance':''))}</h4>${owners.map(key=>{const [role,owner]=key.split('|||'),ot=st.filter(t=>roleForTask(t)===role&&(t.owner||'Unassigned')===owner);return `<div class="milestone-owner"><div class="owner-head"><b>${esc(role)} · ${esc(owner)}</b><span>${ot.length} task${ot.length===1?'':'s'}</span></div>${ot.map(t=>`<div class="drill-task" data-edit-task="${t.id}"><div><b>${esc(t.title)}</b><small>${esc(t.start||'')} → ${esc(t.forecastDue||t.due||'')} · ${esc(t.status||'')}</small></div><div class="reorder-controls"><button class="mini-btn" data-move-task="${t.id}" data-dir="-1">↑</button><button class="mini-btn" data-move-task="${t.id}" data-dir="1">↓</button></div></div>`).join('')}</div>`}).join('')}</div>`}).join('')||'<div class="empty">No linked tasks yet. Add a task and select this milestone.</div>'}</div></details>`}).join('')}</div>`}

taskTable=function(ts,compact=false){const ms=allMilestones();return `<div class="section-title"><h2>${compact?'Value-stream tasks':'Task Control Tower'}</h2><button class="btn primary" id="addTask">+ Task</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Milestone</th><th>Type / Task</th><th>Stream</th><th>Role / Owner</th><th>Priority</th><th>Progress</th><th>Status</th><th>Forecast</th></tr></thead><tbody>${orderedTasks(ts).map(t=>{const fc=t.forecastDue||t.due||'';return `<tr data-edit-task="${t.id}"><td>${esc(t.id)}</td><td>${esc(inferTaskMilestone(t)||'—')}</td><td><small>${esc(t.type||'Activity')}</small><b>${esc(t.title)}</b>${t.dependency?`<small>Depends: ${esc(t.dependency)}</small>`:''}</td><td>${esc(t.stream||'')}</td><td><small>${esc(roleForTask(t))}</small><b>${esc(t.owner||'')}</b></td><td>${badge(t.priority)}</td><td><div class="progress-cell"><span>${taskProgress(t)}%</span><div class="maturity-bar"><i style="width:${taskProgress(t)}%"></i></div></div></td><td><select class="status-select" data-task-status="${t.id}">${['Not Started','In Progress','Waiting','Blocked','Ready for Review','BPO Review','Approved','Closed'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td>${esc(fc)}</td></tr>`}).join('')}</tbody></table></div>`}

editTask=function(id,stream=selectedStream,ownerDefault=''){const arr=state.tasks.tasks||[],x=arr.find(t=>t.id===id),mids=allMilestones(),bo=boProfile(),t=x||{id:uid('T'),type:'Activity',title:'',stream,process:'All',owner:ownerDefault,status:'Not Started',priority:'Medium',progress:0,start:today(),baselineDue:'',forecastDue:'',phase:'',dependency:'',milestoneId:mids[0]?.id||'',ganttOrder:nextTaskOrder(mids[0]?.id||'')};const people=[bo.name,...(data().people||[]).map(p=>p.name)].filter(Boolean);const mm=modal(x?'Edit task / deliverable':'Add task / deliverable',`<div class="form-grid"><label>Milestone<select name="milestoneId"><option value="">Unassigned</option>${mids.map(m=>`<option value="${m.id}" ${inferTaskMilestone(t)===m.id?'selected':''}>${esc(m.id)} · ${esc(m.name)}</option>`).join('')}</select></label><label>Type<select name="type">${options(['Activity','Deliverable','Milestone','Workshop','Approval'],t.type||'Activity')}</select></label><label>Stream<select name="stream">${streamOptions(t.stream)}</select></label><label>Process<input name="process" value="${esc(t.process||'All')}"></label><label class="full">Task / deliverable<input name="title" value="${esc(t.title)}"></label><label>Owner<input name="owner" list="taskOwners" value="${esc(t.owner||ownerDefault)}"><datalist id="taskOwners">${people.map(p=>`<option value="${esc(p)}"></option>`).join('')}</datalist></label><label>Approver<input name="approver" value="${esc(t.approver||'')}"></label><label>Priority<select name="priority">${options(['Critical','High','Medium','Low'],t.priority||'Medium')}</select></label><label>Status<select name="status">${options(['Not Started','In Progress','Waiting','Blocked','Ready for Review','BPO Review','Approved','Closed'],t.status||'Not Started')}</select></label><label>Progress %<input type="number" min="0" max="100" name="progress" value="${taskProgress(t)}"></label><label>Phase<input name="phase" value="${esc(t.phase||'')}"></label><label>Start<input type="date" name="start" value="${esc(t.start||'')}"></label><label>Baseline due<input type="date" name="baselineDue" value="${esc(t.baselineDue||t.due||'')}"></label><label>Forecast due<input type="date" name="forecastDue" value="${esc(t.forecastDue||t.due||'')}"></label><label class="full">Dependency<input name="dependency" value="${esc(t.dependency||'')}"></label><label class="full">Blocker / notes<textarea name="blocker" rows="3">${esc(t.blocker||'')}</textarea></label></div><div class="notice"><b>Workplan linkage:</b> every task should be tied to a milestone. The roadmap then drills from milestone → value stream → BPO / SME → task.</div>`);mm.querySelector('.modal-save').onclick=()=>{const oldMid=inferTaskMilestone(t),v=vals(mm);Object.assign(t,v);t.ownerRole=roleForTask(t);t.due=t.forecastDue||t.baselineDue||'';if(!x)arr.push(t);if(!t.ganttOrder||oldMid!==t.milestoneId)t.ganttOrder=nextTaskOrder(t.milestoneId);mark('tasks');mm.remove();render()}}

editMilestone=function(id){const arr=state.milestones.milestones||[],x=arr.find(d=>d.id===id),m0=x||{id:uid('M'),name:'',stream:'Program',owner:'Business Owner',start:today(),end:'',status:'Proposed',description:'',exitCriteria:''};const mm=modal(x?'Edit milestone':'Add milestone',`<div class="form-grid"><label>ID<input name="id" value="${esc(m0.id)}"></label><label>Status<select name="status">${options(['Proposed','In Progress','At Risk','Complete','Closed'],m0.status||'Proposed')}</select></label><label class="full">Milestone<input name="name" value="${esc(m0.name)}"></label><label>Owner<input name="owner" value="${esc(m0.owner||'Business Owner')}"></label><label>Stream<input name="stream" value="${esc(m0.stream||'Program')}"></label><label>Start<input type="date" name="start" value="${esc(m0.start||'')}"></label><label>End<input type="date" name="end" value="${esc(m0.end||'')}"></label><label class="full">Purpose / description<textarea name="description" rows="3">${esc(m0.description||'')}</textarea></label><label class="full">Exit criteria / definition of done<textarea name="exitCriteria" rows="3">${esc(m0.exitCriteria||'')}</textarea></label></div><div class="notice">Tasks are linked to this milestone through the task editor and appear automatically in the milestone drill-down.</div>`);mm.querySelector('.modal-save').onclick=()=>{Object.assign(m0,vals(mm));if(!x)arr.push(m0);mark('milestones');mm.remove();render()}}

renderExecution=function(){const d=data(),ts=d.tasks||[],ms=allMilestones(),blocked=ts.filter(t=>t.status==='Blocked').length,over=ts.filter(t=>!['Closed','Approved'].includes(t.status)&&(t.forecastDue||t.due)&&(t.forecastDue||t.due)<today()).length,unlinked=ts.filter(t=>!inferTaskMilestone(t)).length;return `<div class="page-head"><div><h1>Execution Control</h1><p>One connected workplan: milestone → value stream → BPO / SME → task.</p></div></div><div class="grid kpi">${kpi('Open tasks',ts.filter(t=>!['Closed','Approved'].includes(t.status)).length,'current workload')}${kpi('Overdue',over,'forecast date passed')}${kpi('Blocked',blocked,'requires intervention')}${kpi('Unlinked',unlinked,'tasks without milestone')}</div>${taskTable(ts)}<div class="section-title"><h2>Milestone-linked Gantt</h2><span>use ↑ / ↓ to reorder tasks vertically</span></div>${workplanGantt(ms,ts)}<div class="section-title"><h2>Milestone drill-down</h2><span>value stream → BPO / SME → task</span></div>${milestoneDrilldown(ms,ts)}`}

renderRoadmap=function(){const d=data(),ms=allMilestones(),ts=d.tasks||[];return `<div class="page-head"><div><h1>Program Roadmap & Work Breakdown</h1><p>Program milestones are the parent structure for all value-stream, BPO, SME and Business Owner tasks.</p></div><button class="btn primary" id="addMilestone">+ Milestone</button></div><div class="section-title"><h2>Integrated program Gantt</h2><span>milestones with linked tasks</span></div>${workplanGantt(ms,ts)}<div class="section-title"><h2>Milestone work breakdown</h2><span>expand a milestone to drill down</span></div>${milestoneDrilldown(ms,ts)}<div class="section-title"><h2>Milestone register</h2></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Milestone</th><th>Owner</th><th>Start</th><th>End</th><th>Tasks</th><th>Progress</th><th>Status</th></tr></thead><tbody>${ms.map(m=>{const mt=ts.filter(t=>inferTaskMilestone(t)===m.id);return `<tr data-edit-milestone="${m.id}"><td>${esc(m.id)}</td><td><b>${esc(m.name)}</b>${m.exitCriteria?`<small>${esc(m.exitCriteria)}</small>`:''}</td><td>${esc(m.owner||'Business Owner')}</td><td>${esc(m.start)}</td><td>${esc(m.end)}</td><td>${mt.length}</td><td>${milestoneProgress(m.id)}%</td><td>${badge(m.status)}</td></tr>`}).join('')}</tbody></table></div>`}

function renderBusinessOwner(){const d=data(),bo=boProfile(),my=(d.tasks||[]).filter(t=>roleForTask(t)==='Business Owner'||t.owner===bo.name),open=my.filter(t=>!['Closed','Approved'].includes(t.status)),over=open.filter(t=>(t.forecastDue||t.due)&&(t.forecastDue||t.due)<today()),dec=(d.decisions||[]).filter(x=>!['Closed','Decided'].includes(x.status)&&(x.owner==='Business Owner'||x.owner===bo.name||x.escalateToSteering===true||x.escalateToSteering==='Yes')),escs=(d.escalations||[]).filter(x=>!['Closed','Resolved'].includes(x.status)),ms=allMilestones();return `<div class="page-head"><div><h1>Business Owner</h1><p>${esc(bo.name)} · enterprise accountability, decisions, escalations and personal workplan.</p></div><div class="button-row"><button class="btn" id="editBoProfile">Edit responsibilities</button><button class="btn primary" id="addBoTask">+ My task</button></div></div><div class="grid kpi">${kpi('My open tasks',open.length,'across program milestones')}${kpi('Overdue',over.length,'forecast date passed')}${kpi('Decision queue',dec.length,'requires business-owner attention')}${kpi('Steering escalations',escs.length,'open committee items')}</div><div class="grid bo-main"><div><div class="section-title"><h2>My responsibilities</h2><span>Business Owner charter</span></div><div class="card pad responsibility-card"><ol>${(bo.responsibilities||DEFAULT_BO.responsibilities).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div></div><div><div class="section-title"><h2>Immediate attention</h2><span>open exceptions</span></div><div class="card pad">${over.slice(0,5).map(t=>`<div class="attention-item red" data-edit-task="${t.id}"><span>Overdue task</span><b>${esc(t.title)}</b><small>${esc(t.forecastDue||t.due)}</small></div>`).join('')}${dec.slice(0,5).map(x=>`<div class="attention-item yellow" data-edit-decision="${x.id}"><span>Decision</span><b>${esc(x.title)}</b><small>${esc(x.due||'No due date')}</small></div>`).join('')}${!over.length&&!dec.length?'<div class="empty">No overdue Business Owner tasks or open decisions.</div>':''}</div></div></div><div class="section-title"><h2>My milestone workplan</h2><span>linked to the enterprise roadmap</span></div>${workplanGantt(ms,my)}<div class="section-title"><h2>My tasks</h2></div>${taskTable(my)}<div class="grid two-col"><div><div class="section-title"><h2>Decision queue</h2><span>${dec.length}</span></div>${decisionTable(dec)}</div><div><div class="section-title"><h2>Steering Committee escalations</h2><span>${escs.length}</span></div><div class="card pad">${escs.map(x=>`<div class="decision-log-item" data-edit-escalation="${x.id}"><span>${esc(x.id)} · ${esc(x.committeeDate||'date TBD')}</span><b>${esc(x.title)}</b><small>${esc(x.recommendation||x.reason||'')}</small></div>`).join('')||'<div class="empty">No open escalations.</div>'}</div></div></div>`}
function editBusinessOwner(){const existing=state.framework.businessOwner,bo=existing||clone(DEFAULT_BO);const mm=modal('Business Owner profile',`<div class="form-grid"><label class="full">Name<input name="name" value="${esc(bo.name||'')}"></label><label class="full">Role<input name="role" value="${esc(bo.role||'Business Owner')}"></label><label class="full">Responsibilities<textarea name="responsibilitiesText" rows="12">${esc((bo.responsibilities||DEFAULT_BO.responsibilities).join('\n'))}</textarea></label></div>`);mm.querySelector('.modal-save').onclick=()=>{const v=vals(mm);state.framework.businessOwner={name:v.name,role:v.role,responsibilities:String(v.responsibilitiesText||'').split('\n').map(x=>x.trim()).filter(Boolean)};mark('framework');mm.remove();render()}}

const previousBind=bindPage;
bindPage=function(){previousBind();$$('[data-move-task]').forEach(b=>b.onclick=e=>{e.stopPropagation();moveTaskInGantt(b.dataset.moveTask,Number(b.dataset.dir)||0)});$('#addBoTask')?.addEventListener('click',()=>editTask(null,'Program',boProfile().name));$('#editBoProfile')?.addEventListener('click',editBusinessOwner)};
const previousRender=render;
render=function(){if(view==='businessowner'){ensureV2State();const app=$('#app');app.innerHTML=renderBusinessOwner();bindPage();return}previousRender()};
})();
